                post_hook={
                    "sql": "create or replace table sleepycat_db.maplemonk.po_grn_analysis as with base as ( select po_id, grn_Id, grn_status, po_created_date::Date po_Date, inwarded_WArehouse, grn.value:model_no::string sku, sum(grn.value:available::float) grn_quantity, sum(grn.value:original_quantity::float) po_quantity, from sleepycat_db.maplemonk.easyecom_sleepycat_grn_details, LATERAL FLATTEN(input => grn_items) AS grn, group by 1,2,3,4,5,6 ) select b.*,sm_category as Category,sub_category from base b left join ( select upper(trim(marketplace_sku)) as sm_sku, category as sm_category, sub_category from sleepycat_db.maplemonk.final_sku_master qualify row_number() over(partition by upper(trim(marketplace_sku)) order by 1) = 1 )sm on lower(trim(b.sku)) = lower(trim(sm.sm_sku)) ; create or replace table sleepycat_db.maplemonk.sleepycat_fifo_report as select CONVERT_TIMEZONE(\'Asia/Kolkata\',TO_TIMESTAMP_TZ(_AIRBYTE_NORMALIZED_AT))::DATE AS Data_Fetch_Date, upper(sku) as sku, \"Company Name\" as Compnay_Name, upper(coalesce(sm_category,category)) as Category, sub_category, \"Days In Warehouse\" days_in_warehouse, sum(quantity) quantity from ( select * from sleepycat_db.maplemonk.easyecom_sleepycat_full_inventory_report qualify DENSE_RANK() over(partition by _airbyte_normalized_at::timestamp::date order by 1 desc) = 1 ) fi left join ( select upper(trim(marketplace_sku)) as sm_sku, category as sm_category, sub_category from sleepycat_db.maplemonk.final_sku_master qualify row_number() over(partition by upper(trim(marketplace_sku)) order by 1) = 1 )sm on lower(trim(fi.sku)) = lower(trim(sm.sm_sku)) where lower(status) in (\'available\',\'reserved\') and lower(\"Company Name\") in (\'vsl-cdp\', \'central distribution point\', \'sleep management pvt tdl mumbai warehouse\',\'sleep management pvt ltd chennai warehouse\',\'sleep management farukhnagar\',\'sleep management pvt ltd bangalore new warehouse\',\'hyderabad warehouse\', \'sleep management kolkata\') group by 1,2,3,4,5,6 ; Create Or Replace table sleepycat_db.maplemonk.sleepycat_db_warehouse_capacity_tracker as With Base as ( select DATEADD(day, 1, TO_TIMESTAMP(\"Report Generated Date\", \'YYYY-MM-DD HH24:MI:SS\'))::date DATA_FETCH_DATE, replace(replace(SKU,\'\\'\',\'\'),\'`\',\'\') SKU, Location as Warehouse, coalesce(a1.name,a2.name) Name, coalesce(a1.CATEGORY,a2.CATEGORY) CATEGORY, coalesce(a1.SUB_CATEGORY,a2.SUB_CATEGORY) SUB_CATEGORY, upper(trim(coalesce(a1.CAPACITY_CATEGORY,a2.CAPACITY_CATEGORY))) as CAPACITY_CATEGORY, sum(\"Available Quantity\"::int) AVAILABLEINVENTORY, from ( select * from sleepycat_db.maplemonk.sleepycat_db_inventory_snapshot qualify row_number() over (partition by location, \"Company Token\", SKU, DATEADD(day, 1, TO_TIMESTAMP(\"Report Generated Date\", \'YYYY-MM-DD HH24:MI:SS\'))::date order by \"Report Generated Date\") = 1 )s left join ( select * from sleepycat_db.maplemonk.final_sku_master qualify ROW_NUMBER() OVER(partition by MARKETPLACE_SKU order by 1) = 1 )a1 on lower(replace(replace(s.SKU,\'\\'\',\'\'),\'`\',\'\')) = lower(a1.MARKETPLACE_SKU) left join ( select * from sleepycat_db.maplemonk.final_sku_master qualify ROW_NUMBER() OVER(partition by skucode order by 1) = 1 )a2 on lower(replace(replace(s.SKU,\'\\'\',\'\'),\'`\',\'\')) = lower(a2.skucode) where DATA_FETCH_DATE is not null group by 1,2,3,4,5,6,7 ) Select b.*,div0(cm.Capacity,count(*) over(partition by lower(trim(b.Capacity_Category)),lower(trim(b.Warehouse)),b.DATA_FETCH_DATE)) as Capacity from Base b left join ( select * from (select upper(trim(warehouse)) as Warehouse ,\'ACC\' as Capacity_Category ,try_cast(ACC as int) as Capacity from sleepycat_db.maplemonk.sleepycat_db_capacity_mapping UNION ALL select upper(trim(warehouse)) as Warehouse ,\'MATTRESS\' as Capacity_Category ,try_cast(MATTRESS as int) as Capacity from sleepycat_db.maplemonk.sleepycat_db_capacity_mapping UNION ALL select upper(trim(warehouse)) as Warehouse ,\'FURNITURE\' as Capacity_Category ,try_cast(FURNITURE as int) as Capacity from sleepycat_db.maplemonk.sleepycat_db_capacity_mapping ) QUALIFY row_number() over(partition by Warehouse,Capacity_Category order by 1) = 1 )cm on lower(trim(b.Capacity_Category)) = lower(trim(cm.Capacity_Category)) and lower(trim(cm.Warehouse)) = lower(trim(b.Warehouse)) ; Create or Replace table SLEEPYCAT_DB.MAPLEMONK.Sleepycat_DB_Returns_performance_GoogleSheet as select SKU, WEEK, Status, Category, Pincode, COURIER, TAT, \"Cover Awb\" as Cover_AWB, \"Order id\" as order_id, \"Reverse Awb\" Reverse_AWB, \"Cover Zone\" Cover_Zone, \"Reverse Zone\" as Reverse_Zone, \"New Status\" as Status2, \"Final Status\", \"Reverse Awb\", TO_DATE(\"Return Raise date\", \'DD-MM-YYYY\') as Return_Raise_Date, TO_DATE(\"ReversePickup Date\", \'DD-MM-YYYY\') as ReturnPickup_Date, DATEDIFF(\'day\', TO_DATE(\"Return Raise date\", \'DD-MM-YYYY\'), TO_DATE(\"ReversePickup Date\", \'DD-MM-YYYY\') ) AS Return_Pickup_TAT from sleepycat_db.maplemonk.sleepycat_db_google_sheet_returns_sheet1; Create Or Replace Table SLEEPYCAT_DB.MAPLEMONK.Sleepycat_db_Inward_TAT_Summary as WITH PO_DATA as ( SELECT PO_ID ,PO_NUMBER ,PO_REF_NUM ,VENDOR_C_ID ,VENDOR_LOCATION_KEY ,UPPER(VENDOR_NAME) VENDOR_NAME ,PO_CREATED_LOCATION_KEY ,UPPER(PO_CREATED_WAREHOUSE) PO_CREATED_WAREHOUSE ,PO_CREATED_WAREHOUSE_C_ID ,try_to_timestamp(PO_CREATED_DATE) PO_CREATED_DATE ,try_to_timestamp(PO_UPDATED_DATE) PO_UPDATED_DATE ,B.VALUE:\"cp_id\" CP_ID ,B.VALUE:\"ean\" EAN ,B.VALUE:\"hsn\" HSN ,B.VALUE:\"model_no\" MODEL_NO ,B.VALUE:\"product_id\" PRODUCT_ID ,upper(B.VALUE:\"sku\"::string) SKU ,B.VALUE:\"product_description\" PRODUCT_DESCRIPTION ,B.VALUE:\"purchase_order_detail_id\" PO_DETAIL_ID ,B.VALUE:\"original_quantity\"::float ORIGINAL_QUANTITY ,B.VALUE:\"pending_quantity\"::float PENDING_QUANTITY ,B.VALUE:\"item_price\"::float ITEM_PRICE ,PO_STATUS_ID ,upper(case when PO_STATUS_ID = 3 then \'Pending\' when PO_STATUS_ID = 4 then \'Approved\' when PO_STATUS_ID = 5 then \'Partially Fulfilled\' when PO_STATUS_ID = 7 then \'Completed\' else \'Others\' end) as PO_STATUS from Sleepycat_db.MAPLEMONK.ee_sleepycat_purchase_orders A, LATERAL FLATTEN (INPUT => A.PO_ITEMS) B qualify row_number() over(partition by PO_ID,PO_REF_NUM,upper(B.VALUE:\"sku\"::string) order by _airbyte_normalized_at desc) = 1 ), GRN_DATA as ( SELECT A.GRN_ID ,A.PO_ID ,A.PO_NUMBER ,A.PO_REF_NUM ,A.VENDOR_C_ID ,UPPER(A.VENDOR_NAME) AS VENDOR_NAME ,A.INWARDED_WAREHOUSE ,A.INWARDED_WAREHOUSE_C_ID ,TRY_TO_TIMESTAMP(A.GRN_CREATED_AT) AS GRN_CREATED_AT ,TRY_TO_TIMESTAMP(A.PO_CREATED_DATE) AS PO_CREATED_DATE ,TRY_TO_TIMESTAMP(A.PO_UPDATED_DATE) AS PO_UPDATED_DATE ,TRY_TO_DATE(A.GRN_INVOICE_DATE) AS GRN_INVOICE_DATE ,A.GRN_INVOICE_NUMBER ,A.TOTAL_GRN_VALUE ,B.VALUE:\"grn_detail_id\"::NUMBER AS GRN_DETAIL_ID ,B.VALUE:\"cp_id\"::NUMBER AS CP_ID ,B.VALUE:\"ean\"::STRING AS EAN ,B.VALUE:\"hsn\"::STRING AS HSN ,B.VALUE:\"model_no\"::STRING AS MODEL_NO ,B.VALUE:\"product_id\"::NUMBER AS PRODUCT_ID ,UPPER(B.VALUE:\"sku\"::STRING) AS SKU ,B.VALUE:\"product_name\"::STRING AS PRODUCT_NAME ,B.VALUE:\"product_description\"::STRING AS PRODUCT_DESCRIPTION ,B.VALUE:\"purchase_order_detail_id\"::NUMBER AS PO_DETAIL_ID ,B.VALUE:\"original_quantity\"::FLOAT AS ORIGINAL_QUANTITY ,B.VALUE:\"pending_quantity\"::FLOAT AS PENDING_QUANTITY ,B.VALUE:\"received_quantity\"::FLOAT AS RECEIVED_QUANTITY ,B.VALUE:\"grn_detail_price\"::FLOAT AS GRN_DETAIL_PRICE ,B.VALUE:\"qc_pass\"::FLOAT AS QC_PASS ,B.VALUE:\"qc_fail\"::FLOAT AS QC_FAIL ,B.VALUE:\"qc_pending\"::FLOAT AS QC_PENDING ,B.VALUE:\"damaged\"::FLOAT AS DAMAGED ,B.VALUE:\"repair\"::FLOAT AS REPAIR ,B.VALUE:\"lost\"::FLOAT AS LOST ,B.VALUE:\"discard\"::FLOAT AS DISCARD ,B.VALUE:\"available\"::FLOAT AS AVAILABLE ,B.VALUE:\"reserved\"::FLOAT AS RESERVED ,B.VALUE:\"sold\"::FLOAT AS SOLD ,B.VALUE:\"transfer\"::FLOAT AS TRANSFER ,B.VALUE:\"return_available\"::FLOAT AS RETURN_AVAILABLE ,B.VALUE:\"return_to_source\"::FLOAT AS RETURN_TO_SOURCE ,B.VALUE:\"used_in_manufacturing\"::FLOAT AS USED_IN_MANUFACTURING ,B.VALUE:\"shelf_id\"::NUMBER AS SHELF_ID ,B.VALUE:\"batch_code\"::STRING AS BATCH_CODE ,TRY_TO_DATE(B.VALUE:\"expire_date\"::STRING) AS EXPIRE_DATE ,B.VALUE:\"expiry\"::FLOAT AS EXPIRY ,B.VALUE:\"near_expiry\"::FLOAT AS NEAR_EXPIRY ,B.VALUE:\"grn_details_status_name\"::STRING AS GRN_DETAIL_STATUS ,A.GRN_STATUS_ID ,UPPER( CASE WHEN A.GRN_STATUS_ID = 3 THEN \'In Progress\' -- Add remaining GRN status mappings once confirmed ELSE \'Others\' END ) AS GRN_STATUS FROM sleepycat_db.maplemonk.easyecom_sleepycat_grn_details A, LATERAL FLATTEN(INPUT => A.GRN_ITEMS) B QUALIFY ROW_NUMBER() OVER (PARTITION BY A.GRN_ID,A.PO_ID,A.PO_REF_NUM,UPPER(B.VALUE:\"sku\"::STRING) ORDER BY A._AIRBYTE_NORMALIZED_AT DESC) = 1 ) Select p.po_id ,p.PO_NUMBER ,p.PO_REF_NUM ,p.PO_CREATED_WAREHOUSE ,p.SKU ,p.PRODUCT_ID ,p.ITEM_PRICE ,p.ORIGINAL_QUANTITY ,p.PO_CREATED_DATE ,g.GRN_CREATED_AT ,g.RECEIVED_QUANTITY ,DATEDIFF(\'day\',p.PO_CREATED_DATE,g.GRN_CREATED_AT) AS PO_TO_GRN_DAYS ,inward_tat_as_per_po_creation_date ,case when PO_TO_GRN_DAYS < inward_tat_as_per_po_creation_date then \'IN-TAT\' when PO_TO_GRN_DAYS > inward_tat_as_per_po_creation_date then \'OUT-TAT\' end as TAT ,coalesce(a1.CAPACITY_CATEGORY,a2.CAPACITY_CATEGORY) as Category from po_data p left join grn_data g on lower(trim(p.po_id)) = lower(trim(g.po_id)) and lower(trim(p.PO_REF_NUM)) = lower(trim(g.PO_REF_NUM)) and lower(trim(p.sku)) = lower(trim((g.sku))) left join ( select warehouse_name ,inward_tat_as_per_po_creation_date from SLEEPYCAT_DB.MAPLEMONK.warehouse_inTAT_Mapping )mp on lower(trim(p.PO_CREATED_WAREHOUSE))= lower(trim(mp.warehouse_name)) left join ( select * from sleepycat_db.maplemonk.final_sku_master qualify ROW_NUMBER() OVER(partition by MARKETPLACE_SKU order by 1) = 1 )a1 on lower(replace(replace(p.sku,\'\\'\',\'\'),\'`\',\'\')) = lower(a1.MARKETPLACE_SKU) left join ( select * from sleepycat_db.maplemonk.final_sku_master qualify ROW_NUMBER() OVER(partition by skucode order by 1) = 1 )a2 on lower(replace(replace(p.SKU,\'\\'\',\'\'),\'`\',\'\')) = lower(a2.skucode) where lower(p.PO_CREATED_WAREHOUSE) in (\'sleep management pvt tdl mumbai warehouse\',\'sleep management pvt ltd chennai warehouse\',\'sleep management farukhnagar\',\'sleep management pvt ltd bangalore new warehouse\',\'hyderabad warehouse\', \'sleep management kolkata\') ;",
                    "transaction": true
